// Package testutil holds the helpers the tests share: fixture loading (testdata/*.json or *.json.gz, generated by
// running the Python code) and a JSON comparison with a relative tolerance for numbers.
package testutil

import (
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"testing"
)

// Load reads testdata/<name>.json (or .json.gz) of the module into v. Tests run in internal/<pkg>.
func Load(t testing.TB, name string, v any) {
	t.Helper()
	base := filepath.Join("..", "..", "testdata", name)
	var r io.Reader
	if f, err := os.Open(base + ".json"); err == nil {
		defer f.Close()
		r = f
	} else if f, err := os.Open(base + ".json.gz"); err == nil {
		defer f.Close()
		zr, err := gzip.NewReader(f)
		if err != nil {
			t.Fatal(err)
		}
		defer zr.Close()
		r = zr
	} else {
		t.Fatalf("fixture %s not found", name)
	}
	if err := json.NewDecoder(r).Decode(v); err != nil {
		t.Fatalf("fixture %s: %v", name, err)
	}
}

// Close is |a-b| <= rel * max(|a|, |b|) (plus a tiny absolute slack for values around zero).
func Close(a, b, rel float64) bool {
	if a == b || (math.IsNaN(a) && math.IsNaN(b)) {
		return true
	}
	return math.Abs(a-b) <= rel*math.Max(math.Abs(a), math.Abs(b))+1e-14
}

// Diff compares two decoded JSON values: strings, bools, keys and lengths exactly, numbers within rel.
// It returns "" when equal, else the path of the first difference.
func Diff(want, got any, rel float64) string {
	return diff("$", want, got, rel)
}

func diff(path string, want, got any, rel float64) string {
	switch w := want.(type) {
	case nil:
		if got != nil {
			return fmt.Sprintf("%s: want null, got %v", path, got)
		}
	case float64:
		g, ok := got.(float64)
		if !ok {
			return fmt.Sprintf("%s: want number %v, got %v", path, w, got)
		}
		if !Close(w, g, rel) {
			return fmt.Sprintf("%s: want %v, got %v", path, w, g)
		}
	case string:
		if g, ok := got.(string); !ok || g != w {
			return fmt.Sprintf("%s: want %q, got %v", path, w, got)
		}
	case bool:
		if g, ok := got.(bool); !ok || g != w {
			return fmt.Sprintf("%s: want %v, got %v", path, w, got)
		}
	case []any:
		g, ok := got.([]any)
		if !ok {
			return fmt.Sprintf("%s: want list, got %v", path, got)
		}
		if len(g) != len(w) {
			return fmt.Sprintf("%s: want %d items %v, got %d %v", path, len(w), w, len(g), g)
		}
		for i := range w {
			if d := diff(fmt.Sprintf("%s[%d]", path, i), w[i], g[i], rel); d != "" {
				return d
			}
		}
	case map[string]any:
		g, ok := got.(map[string]any)
		if !ok {
			return fmt.Sprintf("%s: want object, got %v", path, got)
		}
		var keys []string
		for k := range w {
			keys = append(keys, k)
		}
		for k := range g {
			if _, ok := w[k]; !ok {
				keys = append(keys, k)
			}
		}
		sort.Strings(keys)
		for _, k := range keys {
			wv, wok := w[k]
			gv, gok := g[k]
			if wok != gok {
				return fmt.Sprintf("%s.%s: present in want=%v, in got=%v", path, k, wok, gok)
			}
			if d := diff(path+"."+k, wv, gv, rel); d != "" {
				return d
			}
		}
	default:
		return fmt.Sprintf("%s: unsupported type %T", path, want)
	}
	return ""
}

// Roundtrip marshals v and decodes it again into a generic JSON value.
func Roundtrip(t testing.TB, v any) any {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	return out
}
